117					t.Fatalf("expected %d admitted records, got %#v", len(want), results)
118				}
119				for i, w := range want {
120					got := results[i]
121					if got["line"] != w.line || got["ok"] != true {
122						t.Fatalf("record %d must keep physical line %v and ok:true: %#v", i, w.line, got)
123					}
124					if _, marked := got["filtered"]; marked {
125						t.Fatalf("record %d must carry no filter marker: %#v", i, got)
126					}
127					event := eventOf(t, got)
128					if event["action"] != w.action || event["source_ip"] != w.source {
129						t.Fatalf("record %d event mismatch: %#v", i, event)
130					}
131				}
132			})
133		}
134	}
135	
136	// The /31 two-address network through the CLI: both addresses of the pair
137	// survive — neither is treated as a network or broadcast address — the
138	// immediate neighbors do not, and spelling the option with the pair's other
139	// address produces byte-identical output.
140	func TestNormalizeCLISourceCIDRSlash31KeepsBothAddresses(t *testing.T) {
141		input := strings.Join([]string{
142			validCIDRSource("below", "192.0.2.1"),
143			validCIDRSource("low-of-pair", "192.0.2.2"),
144			validCIDRSource("high-of-pair", "192.0.2.3"),
145			validCIDRSource("above", "192.0.2.4"),
146		}, "\n") + "\n"
147	
148		var outputs []string
149		for _, spelled := range []string{"192.0.2.3/31", "192.0.2.2/31"} {
150			result := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", spelled)
151			if result.exitCode != 0 || result.stderr != "" {
152				t.Fatalf("filter %q must run clean: exit=%d stderr=%q", spelled, result.exitCode, result.stderr)
153			}
154			results := decodeStdoutResults(t, result.stdout)
155			if len(results) != 2 {
156				t.Fatalf("filter %q must keep exactly the two addresses of the pair, got %#v", spelled, results)
157			}
158			for i, w := range []struct {
159				line   float64
160				action string
161				source string
162			}{
163				{2, "low-of-pair", "192.0.2.2"},
164				{3, "high-of-pair", "192.0.2.3"},
165			} {
166				if results[i]["line"] != w.line || results[i]["ok"] != true {
167					t.Fatalf("filter %q: record %d must keep physical line %v: %#v", spelled, i, w.line, results[i])
168				}
169				event := eventOf(t, results[i])
170				if event["action"] != w.action || event["source_ip"] != w.source {
171					t.Fatalf("filter %q: record %d event mismatch: %#v", spelled, i, event)
172				}
173			}
174			outputs = append(outputs, result.stdout)
175		}
176		if outputs[0] != outputs[1] {
177			t.Fatalf("the two host spellings of one /31 must produce identical output:\n%s\nvs\n%s",
178				outputs[0], outputs[1])
179		}
180	}
181	
182	// A time-invalid log whose source lies immediately outside the /17 range is
183	// still a counted failure — physical line number, timestamp reason, no event
184	// — and the in-range logs around it keep their input order and physical line
185	// numbers. Exit 1, stderr empty.
186	func TestNormalizeCLISourceCIDRBoundaryFailureStillCounted(t *testing.T) {
187		input := strings.Join([]string{
188			validCIDRSource("range-first", "192.0.128.0"),                              // line 1 kept
189			`{"timestamp":"not-a-time","action":"broken","source_ip":"192.0.127.255"}`, // line 2 failure, just outside
190			"",                                      // line 3 blank
191			validCIDRSource("dropped", "192.1.0.0"), // line 4 dropped, just outside
192			validCIDRSource("range-last", "192.0.255.255"), // line 5 kept
193		}, "\n") + "\n"
194	
195		result := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", "192.0.129.7/17")
196	
197		if result.exitCode != 1 {
198			t.Fatalf("the invalid line must force exit 1 even though its source is out of range, got %d", result.exitCode)
199		}
200		if result.stderr != "" {
201			t.Fatalf("per-line reasons belong in stdout records, not stderr, got %q", result.stderr)
202		}
