28	// timePairLine builds one log object carrying tsA and tsB under the
29	// canonical name and the alias in the requested assignment and member order.
30	func timePairLine(firstKey, firstTS, secondKey, secondTS, action string) string {
31		return `{"` + firstKey + `":"` + firstTS + `","` + secondKey + `":"` + secondTS + `","action":"` + action + `"}`
